package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenDecimalAddSubScopeTest {
 private static final String SYSTEM="na-nied-primary-2024-v1";
 private static Question q(String id,String prompt){return new Question(id,prompt,"private expression","999");}
 @Test public void NormalNaSevenBothOperationsRemainTypedAcrossAllArityAndPrecisionShapes(){
  var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(SYSTEM)).findFirst().orElseThrow();for(String id:List.of("decimalAdd","decimalSub")){assertTrue(pack.inGrade(id,7));assertEquals(1,Catalog.ALL.stream().filter(s->s.id.equals(id)).count());CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,id,7);assertTrue(limits.decimalDirectAnswers());assertTrue(limits.variedFacts());assertEquals(99,limits.wholeMaximum(1));assertEquals(3,limits.decimalPlaces(1));
   for(boolean mc:List.of(false,true)){Generator generator=new Generator(new Random(364));List<String> recent=new ArrayList<>();Set<Integer> arities=new HashSet<>(),places=new HashSet<>();boolean zeroOperand=false;
    for(int i=0;i<200;i++){Question q=generator.next(id,recent,mc,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());List<String> original=DecimalAddSub.read(q);arities.add(original.size());Set<Integer> currentPlaces=new HashSet<>();for(String text:original){BigDecimal n=new BigDecimal(text);assertTrue(n.signum()>=0&&n.compareTo(new BigDecimal("100"))<0);assertTrue(n.scale()<=3);currentPlaces.add(n.scale());places.add(n.scale());zeroOperand|=n.signum()==0;}assertTrue(currentPlaces.size()>1);assertTrue(DecimalAddSub.value(q).signum()>=0);assertTrue(limits.allows(q));assertEquals("number",q.kind);assertEquals("decimalValue",q.answerFormat);assertTrue(q.choices.isEmpty());assertEquals(-1,q.correctChoice);assertTrue(new Checker().check(q,List.of(),List.of(DecimalAddSub.value(q).toPlainString())).correct());assertEquals(original.size()==2?8:3*original.size()+2,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());}
    assertEquals(Set.of(2,3,4),arities);assertEquals(Set.of(0,1,2,3),places);assertTrue(zeroOperand);
   }Question created=new Generator(new Random(364)).create(Catalog.get(id));assertFalse(DecimalAddSub.read(created).isEmpty());
  }
  for(String[] row:new String[][]{{"decimalAdd","0.999 + 0.001","1"},{"decimalSub","1.000 − 0.001","0.999"},{"decimalAdd","0 + 0.00 + 0.000","0"}}){Question q=q(row[0],row[1]);assertTrue(GlobalCurriculum.limits(SYSTEM,row[0],7).allows(q));assertTrue(new Checker().check(q,List.of(),List.of(row[2])).correct());}
 }
 @Test public void PublicOriginalScaleAndExactResultControlsAreIndependentOfStoredMathAndGradeCaps(){
  Question q=q("decimalAdd","0.1 + 0.2");q.answers=null;q.expression=null;assertTrue(new CurriculumLimits("maxResult=0.3;answerDecimalPlaces=1;nonnegative=true").allows(q));assertFalse(new CurriculumLimits("maxResult=0.299").allows(q));assertTrue(new CurriculumLimits("maxGiven=0.2;minGiven=0.1").allows(q));assertFalse(new CurriculumLimits("maxGiven=0.19").allows(q));assertFalse(new CurriculumLimits("minGiven=0.11").allows(q));assertTrue(CurriculumLimits.NONE.allows(q));assertNull(q.answers);assertNull(q.expression);
  Question general=q("decimalAdd","1.2345 + 2");assertTrue(CurriculumLimits.NONE.allows(general));assertFalse(GlobalCurriculum.limits(SYSTEM,"decimalAdd",7).allows(general));assertTrue(GlobalCurriculum.limits("ke-kicd-cbc-2024-v1","decimalAdd",6).allows(general));assertTrue(new CurriculumLimits("decimalPlaces=4").allows(general));assertFalse(new CurriculumLimits("answerDecimalPlaces=3").allows(general));assertFalse(new CurriculumLimits("answerDomain=integer").allows(general));Question shown=q("decimalAdd","0.1000 + 0.2");assertFalse(new CurriculumLimits("decimalPlaces=3").allows(shown));assertTrue(new CurriculumLimits("answerDecimalPlaces=1").allows(shown));Question signed=q("decimalSub","0.1 − 0.2");assertTrue(CurriculumLimits.NONE.allows(signed));assertFalse(new CurriculumLimits("nonnegative=true").allows(signed));
  Question carry=q("decimalAdd","99.999 + 0.001");assertTrue(GlobalCurriculum.limits(SYSTEM,"decimalAdd",7).allows(carry));assertTrue(new CurriculumLimits("wholeMaximum=99").allows(carry));assertFalse(new CurriculumLimits("maxGiven=99").allows(carry));assertTrue(new CurriculumLimits("maxRegroups=5").allows(carry));assertFalse(new CurriculumLimits("maxRegroups=4").allows(carry));assertFalse(new CurriculumLimits("maxRegroups=9").allows(q("decimalAdd","999999999.999999999999 + 0.000000000001")));assertTrue(new CurriculumLimits("integerSecondOperand=true").allows(q("decimalAdd","0.2 + 1.0")));assertFalse(new CurriculumLimits("integerSecondOperand=true").allows(q("decimalAdd","0.2 + 1.3")));assertFalse(new CurriculumLimits("denominators=2").allows(q));
 }
 @Test public void ExhaustedBoundedHistoryReturnsActualOldestEligibleSignatureAfterFreshPrimaryAttempts(){
  CurriculumLimits limits=new CurriculumLimits("wholeMaximum=1;decimalPlaces=1;variedFacts=true;nonnegative=true;maxGiven=0.000000000001");for(String id:List.of("decimalAdd","decimalSub")){Map<String,Integer> recent=new LinkedHashMap<>();String oldest=null;int age=0;for(int size=2;size<=4;size++)for(int mask=1;mask<(1<<size)-1;mask++){List<String> values=new ArrayList<>();for(int i=0;i<size;i++)values.add((mask&(1<<i))==0?"0":"0.0");Question q=DecimalAddSub.make(id,values);if(oldest==null)oldest=q.signature();recent.put(q.signature(),age++);}recent.put(id+"|0"+(id.equals("decimalAdd")?" + ":" − ")+"0",-1);recent.put(id+"|100"+(id.equals("decimalAdd")?" + ":" − ")+"0.0",-2);Question selected=DecimalAddSub.next(id,new Random(364),limits,recent);assertEquals(22,age);assertEquals(oldest,selected.signature());assertTrue(limits.allows(selected));assertTrue(new Checker().check(selected,List.of(),List.of("0")).correct());}
  CurriculumLimits impossible=new CurriculumLimits("wholeMaximum=1;decimalPlaces=1;variedFacts=true;minGiven=99;maxGiven=100");try{DecimalAddSub.next("decimalAdd",new Random(364),impossible,Map.of());fail("Empty declared supply should not invent a candidate");}catch(IllegalStateException expected){}
 }
 @Test public void NaFiveSixSignaturesChoicesAndSharedMultiplicationDivisionRemainUnchanged(){
  for(String id:List.of("decimalAdd","decimalSub")){CurriculumLimits six=GlobalCurriculum.limits(SYSTEM,id,6),seven=GlobalCurriculum.limits(SYSTEM,id,7),five=GlobalCurriculum.limits(SYSTEM,id,5);assertFalse(six.decimalDirectAnswers());assertFalse(five.decimalDirectAnswers());assertEquals(2,five.decimalPlaces(1));assertEquals(3,six.decimalPlaces(1));Generator a=new Generator(new Random(3641)),b=new Generator(new Random(3641));for(int i=0;i<80;i++)assertEquals(a.next(id,List.of(),false,six).signature(),b.next(id,List.of(),false,seven).signature());Question legacyTyped=new Generator(new Random(3642)).next(id,List.of(),true,six);assertTrue(legacyTyped.choices.isEmpty());assertEquals(-1,legacyTyped.correctChoice);Question sameSeedTyped=new Generator(new Random(3642)).next(id,List.of(),false,six);assertEquals(sameSeedTyped.signature(),legacyTyped.signature());assertEquals(sameSeedTyped.answerFormat,legacyTyped.answerFormat);assertTrue(new Checker().check(legacyTyped,List.of(),List.of(DecimalAddSub.value(legacyTyped).toPlainString())).correct());Question choices=new Generator(new Random(3642)).next(id,List.of(),true,five);assertNotNull(choices.choiceInputs);assertFalse(choices.choices.isEmpty());assertTrue(choices.correctChoice>=0);assertTrue(new Checker().check(choices,List.of(),List.of(choices.choices.get(choices.correctChoice))).correct());assertTrue(DecimalAddSub.selected(id,six));assertFalse(DecimalAddSub.selected(id,five));}
  for(String id:List.of("decimalMul","decimalDivInt")){Question q=new Generator(new Random(3643)).next(id,List.of(),false);StudyGuide stored=q.studyGuide;assertNotNull(stored);HelpPlan plan=HelpPlan.forQuestion(q);assertNotNull(plan);assertEquals(stored.teachingVersion,q.studyGuide.teachingVersion);assertEquals(stored.frames.size(),plan.size());assertEquals(stored.frames.size(),q.studyGuide.frames.size());for(int stage=0;stage<stored.frames.size();stage++){StudyGuide.Frame before=stored.frames.get(stage),after=q.studyGuide.frames.get(stage);assertEquals(before.instruction,after.instruction);assertEquals(before.before,after.before);assertEquals(before.after,after.after);assertEquals(before.expected,after.expected);assertEquals(before.inputFormat,after.inputFormat);assertTrue(plan.step(stage).accepts(before.expected));}assertEquals("decimal-arithmetic-relations-v1",stored.teachingVersion);assertFalse(plan.canTransfer());}Question publicOnly=q("decimalAdd","1.2 + 0.03");publicOnly.studyGuide=new StudyGuide().step("private","private","","999");assertEquals(8,HelpPlan.forQuestion(publicOnly).size());assertEquals("private",publicOnly.studyGuide.frames.get(0).instruction);
 }
}
